/* prog24_query_string_parser.c
 *
 * Re‑implementation of the original program.
 * Reads one line from stdin, parses it as a URL‑encoded query string,
 * decodes each key/value pair and prints them.
 *
 * If no line is read, prints "NO_INPUT".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE   2048          /* size of the input buffer */
#define MAX_DECODE 2048          /* size of the decoded key/value buffers */

/* -------------------------------------------------------------
 * URL‑decode a substring.
 *
 * src   – pointer to the start of the substring
 * len   – length of the substring (may be 0)
 * dst   – buffer where the decoded string is written; must be large
 *         enough to hold the result (len + 1 is sufficient)
 *
 * The function follows the standard rules:
 *   '+'  → space
 *   "%XY" → byte with hexadecimal value XY
 *   otherwise the character is copied unchanged.
 * The result is NUL‑terminated.
 * ------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* convert two hex digits */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int  val = (isdigit((unsigned char)hi) ? hi - '0' :
                       (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' :
                               (tolower((unsigned char)lo) - 'a' + 10));
            dst[o++] = (char)val;
            i += 3;
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
}

/* -------------------------------------------------------------
 * Main program.
 * ------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key_buf[MAX_DECODE];
    static char val_buf[MAX_DECODE];

    /* read one line */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* strip trailing newline and carriage‑return */
    size_t line_len = strlen(line);
    while (line_len > 0 &&
          (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
        line[--line_len] = '\0';
    }

    /* parse the line: tokens are separated by '&' */
    const char *p = line;
    while (*p != '\0') {
        /* locate the end of the current token */
        const char *token_end = strchr(p, '&');
        if (!token_end)
            token_end = p + strlen(p);   /* last token */

        /* locate '=' inside the token (if any) */
        const char *eq = memchr(p, '=', (size_t)(token_end - p));

        if (eq) {
            /* key = characters before '=', value = after '=' */
            size_t key_len = (size_t)(eq - p);
            size_t val_len = (size_t)(token_end - (eq + 1));

            url_decode(p,          key_len, key_buf);
            url_decode(eq + 1,    val_len, val_buf);
        } else {
            /* no '=', value is empty */
            url_decode(p, (size_t)(token_end - p), key_buf);
            val_buf[0] = '\0';
        }

        printf("%s=%s\n", key_buf, val_buf);

        /* advance to the next token (skip the '&' if present) */
        p = (*token_end == '&') ? token_end + 1 : token_end;
    }

    return 0;
}
